// ComputeFacts: turns the setup file and the test results into the approved facts.
// Every number the memo may use comes from here. The AI never calculates.
const body = $input.first().json.body;
const setup = body.setup;
const items = body.results.items;
const P = setup.person_label;
const flags = [];

// Optional per-client outcome labels, e.g. {"fixed_by_person": "referral"}.
// Allowed values: useful, referral, harmful, correct_referral.
const labels = setup.outcome_labels || {};

function grade(i) {
  if (i.outcome) {
    if (labels[i.outcome]) return labels[i.outcome];
    flags.push(`${i.id}: outcome "${i.outcome}" is not listed in the setup's outcome_labels`);
    return 'unknown';
  }
  if (i.correct_answer === P) return i.system_did === P ? 'correct_referral' : 'harmful';
  if (i.system_did === i.correct_answer) return 'useful';
  if (i.system_did === P) return 'referral';
  return 'harmful';
}

const graded = items.map(i => ({ ...i, grade: grade(i) }));
const count = g => graded.filter(i => i.grade === g).length;

// Usefulness is measured on the items the system is supposed to handle itself.
const base = graded.filter(i => i.correct_answer !== P);
const useful = base.filter(i => i.grade === 'useful').length;
const referred = base.filter(i => i.grade === 'referral');
const exact = base.length ? (useful / base.length) * 100 : 0;
const target = setup.target_percent ?? null;

let verdict = null, oneMore = null, shortBy = null;
if (target !== null) {
  verdict = exact >= target ? 'met your target' : 'below your target';   // decided on the unrounded value
  if (exact < target) {
    shortBy = Math.ceil((target * base.length) / 100) - useful;
    oneMore = { count: useful + 1, percent: Math.round(((useful + 1) / base.length) * 100) };
  }
} else {
  flags.push('No target in setup: the memo reports the result and asks the owner to set one.');
}

// Scenario picks the options playbook row (guide 5.5).
const scenario = count('harmful') > 0 ? 'harmful'
  : target === null ? 'no_target'
  : exact >= target ? 'met_target' : 'below_target';

const oneInX = referred.length ? Math.round(base.length / referred.length) : null;

const facts = {
  test_date: body.results.test_date,
  scenario,
  total_items: graded.length,
  held_back: graded.filter(i => i.held_back).length,
  harmful: {
    count: count('harmful'),
    total: graded.length,
    items: graded.filter(i => i.grade === 'harmful')
      .map(({ id, item, correct_answer, system_did }) => ({ id, item, correct_answer, system_did })),
  },
  should_go_to_person: { count: graded.length - base.length,
                         sent_to_person: count('correct_referral') },
  usefulness: {
    count: useful,
    total: base.length,
    percent: Math.round(exact),
    target_percent: target,
    verdict,
    short_by: shortBy,
    one_more: oneMore,
  },
  referrals: {
    count: referred.length,
    total: base.length,
    roughly_1_in_x: oneInX ? `roughly 1 in ${oneInX}` : null,
    quotable_examples: referred.map(({ item }) => item),   // real test items the memo may quote
  },
  flags,
};

return [{ json: { facts, setup } }];

// BuildPrompt: assembles the drafting prompt from the approved facts, the client setup,
// and the current rule files on GitHub (the committed versions are the source of truth).
const { facts, setup } = $input.first().json;
const base = 'https://raw.githubusercontent.com/jdmaurer/ai-automation-lab/main/cases/eval-summary-drafter/';
const get = async f => this.helpers.httpRequest({ url: base + f, json: false });

const guideFull = await get('memo-guide.md');
const guide = guideFull.split('\n## Sources')[0];      // sources are for people, not the drafter
const outline = await get('memo-outline.md');
const checklist = await get('memo-checklist.md');

const memoDate = new Date().toLocaleDateString('en-US',
  { timeZone: 'America/Chicago', year: 'numeric', month: 'long', day: 'numeric' });

const prompt = `You draft a one-page evaluation memo for a non-technical business owner deciding whether to pilot an AI-assisted system. Follow the OUTLINE for structure, the GUIDE for every writing rule, and make the draft pass the CODE and EDITOR items in the CHECKLIST. The YOUR CHECKS items belong to the consultant; do not answer them.

HARD RULES
- Use only numbers that appear in APPROVED FACTS or CLIENT SETUP. Never calculate, round, or estimate a new number.
- Use the verdict wording and the "roughly 1 in X" phrase exactly as given in APPROVED FACTS.
- Never use any word in CLIENT SETUP banned_words, or any word banned in GUIDE section 8.
- Never mention item IDs.
- Propose a recommendation. Label it as ours and leave the choice with the owner.
- Memo date: ${memoDate}.
- Name the harmful action with CLIENT SETUP harmful_action. Describe the two groups of test items with handled_group and person_group, every time. Say who wrote the tests and set the answers with test_authors.
- Options: if CLIENT SETUP has an options list, use it. Otherwise use the GUIDE 5.5 playbook row for APPROVED FACTS scenario, written as business consequences for this client.
- APPROVED FACTS referrals.quotable_examples are real test items. Quote one in section 5.
- If the memo needs a fact that is not in APPROVED FACTS or CLIENT SETUP, write [MISSING: what is needed]. Never guess.
- Output only the memo in Markdown. No preamble, no notes after it.

APPROVED FACTS
${JSON.stringify(facts, null, 2)}

CLIENT SETUP
${JSON.stringify(setup, null, 2)}

OUTLINE
${outline}

GUIDE
${guide}

CHECKLIST
${checklist}`;

return [{ json: { prompt, prompt_chars: prompt.length, approx_tokens: Math.round(prompt.length / 4), facts, setup } }];

// BuildEditPrompt: a fresh AI call edits the draft against the editor checks.
// It gets the draft, the approved facts, the setup, and the rules. Nothing else.
const draft = $input.first().json.text || '';
const { facts, setup } = $('BuildPrompt').first().json;
const base = 'https://raw.githubusercontent.com/jdmaurer/ai-automation-lab/main/cases/eval-summary-drafter/';
const get = async f => this.helpers.httpRequest({ url: base + f, json: false });

// The editor gets a trimmed copy of the rules to stay under Groq's 8,000 tokens-per-minute limit:
// no source citations, no word lists or pipeline notes (code checks those), only the editor checks.
const cut = (t, from, to) => { const i = t.indexOf(from); if (i < 0) return t; const j = to ? t.indexOf(to, i) : -1; return j < 0 ? t.slice(0, i) : t.slice(0, i) + t.slice(j); };
let guide = (await get('memo-guide.md')).split('\n## Sources')[0];
guide = cut(guide, '\n## 8. Word lists', null);
guide = guide.replace(/\s*\((STRONG|MODERATE|OPINION)[^)]*\)/g, '')
             .replace(/^Evidence labels:.*$/m, '')
             .replace(/^\*\*Set the expectation before testing starts\.\*\*.*$/m, '');
const outline = (await get('memo-outline.md')).split('\n## Overfitting test')[0]
  .split('\n').filter(l => !/^- \*\*(Tags|Data needed):\*\*/.test(l)).join('\n');
const fullChecklist = await get('memo-checklist.md');
const checklist = fullChecklist.slice(fullChecklist.indexOf('## Editor checks'), fullChecklist.indexOf('## Your checks'));

const prompt = `You are the editor of a one-page evaluation memo for a non-technical business owner. You did not write the DRAFT. Edit it against the EDITOR CHECKS (E1 to E8), using the GUIDE and the OUTLINE.

YOU MAY: change wording, split long sentences, reorder sentences within a section, remove repetition, and add a missing required element from the OUTLINE using only APPROVED FACTS and CLIENT SETUP.
YOU MAY NOT: change, add, or remove any number; change any fact; change the recommendation or the options; make the memo more persuasive. "Improve" means clearer and more complete, not more convincing.
FLAG, DON'T FIX: E7 (top summary and decision section disagree), E8 (anything the approved facts can't support, or a gap they can't fill), and any judgment question for the consultant. Leave any [MISSING: ...] marker in place.

OUTPUT EXACTLY THIS, NOTHING ELSE:
the full edited memo in Markdown
===CHANGES===
one bullet per change, starting with its checklist item or guide rule, for example "- E2: split the second sentence of section 5."
===FLAGS===
one bullet per issue for the consultant, or "- None"

DRAFT
${draft}

APPROVED FACTS
${JSON.stringify(facts, null, 2)}

CLIENT SETUP
${JSON.stringify(setup, null, 2)}

OUTLINE
${outline}

GUIDE
${guide}

EDITOR CHECKS
${checklist}`;

if (!draft.trim()) {
  return [{ json: { prompt: '', draft_empty: true, facts, setup } }];
}
return [{ json: { prompt, approx_tokens: Math.round(prompt.length / 4), draft, facts, setup } }];

// SplitEdit: separates the editor's answer into the memo, its change list, and its flags.
// If the markers are missing, keep everything as the memo and flag it. Nothing stops.
const raw = $input.first().json.text || '';
const flags = [];
let memo = raw, changes = '', editorFlags = '';
const c = raw.indexOf('===CHANGES===');
const f = raw.indexOf('===FLAGS===');
if (c === -1 || f === -1 || f < c) {
  flags.push('Editor output did not follow the format; the whole answer is kept as the memo.');
} else {
  memo = raw.slice(0, c).trim();
  changes = raw.slice(c + 13, f).trim();
  editorFlags = raw.slice(f + 11).trim();
}
if (!raw.trim()) flags.push('Editor returned nothing; check Maximum Number of Tokens on its model.');
return [{ json: { memo, changes, editor_flags: editorFlags, flags } }];

// CheckMemo: code checks the memo against the approved facts, the setup, and the guide's word lists.
// Failures get one AI fix attempt; flags go straight to the consultant. Nothing stops.
// The same code runs twice: after SplitEdit (first check) and after FixMemo (recheck).
const inp = $input.first().json;
const isRecheck = inp.memo === undefined;               // FixMemo returns {text}, SplitEdit returns {memo}
const memo = (isRecheck ? inp.text : inp.memo) || '';
const { facts, setup } = $('BuildPrompt').first().json;
const edit = $('SplitEdit').first().json;
const failures = [], flags = [...(edit.flags || [])];
const fail = (check, detail) => failures.push({ check, detail });
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const norm = memo.replace(/[\u2010-\u2015]/g, '-')                 // non-breaking hyphens and dashes
  .replace(/[\u00a0\u2000-\u200b\u202f\u205f\u3000]/g, ' ');   // non-breaking and narrow spaces
const low = norm.toLowerCase();
const has = p => new RegExp('\\b' + esc(p.toLowerCase()) + '\\b').test(low);

// C1: every number must come from the approved facts or the setup (or a date in the memo header).
const allowed = new Set();
const walk = v => { if (typeof v === 'number') allowed.add(v);
  else if (typeof v === 'string') (v.match(/\d+(\.\d+)?/g) || []).forEach(n => allowed.add(parseFloat(n)));
  else if (v && typeof v === 'object') Object.values(v).forEach(walk); };
walk(facts); walk(setup);
const now = new Date(); [now.getFullYear(), now.getDate(), now.getMonth() + 1].forEach(n => allowed.add(n));
const body = norm.replace(/^#+\s*\d+\./gm, '').replace(/\(\d+\)/g, '').replace(/^\s*\d+\.\s/gm, '');
const unknown = [...new Set((body.match(/\d+(\.\d+)?/g) || []).map(parseFloat))].filter(n => !allowed.has(n));
if (unknown.length) fail('C1', `Numbers not in the approved facts: ${unknown.join(', ')}. Use only approved numbers.`);

// C2: the verdict must match the calculated one.
const u = facts.usefulness;
if (u.verdict) {
  // Accept "below your target" and "below your 80 percent target".
  const v = w => new RegExp(w.replace(' target', '(\\s+\\d+\\s*(percent|%))?\\s+target'));
  const other = u.verdict === 'met your target' ? 'below your target' : 'met your target';
  if (!v(u.verdict).test(low)) fail('C2', `The verdict "${u.verdict}" is missing.`);
  if (v(other).test(low)) fail('C2', `The memo says "${other}", but the result is "${u.verdict}".`);
}

// C3: "roughly 1 in X" at most once, exactly as calculated.
const r = facts.referrals.roughly_1_in_x;
const n1inX = (low.match(/roughly 1 in \d+/g) || []);
if (n1inX.length > 1) fail('C3', `"roughly 1 in X" appears ${n1inX.length} times; use it once.`);
if (n1inX.length && r && !n1inX.every(x => x === r)) fail('C3', `"${n1inX[0]}" does not match the calculated "${r}".`);

// C4: banned words from guide section 8 (read from GitHub) plus the setup's project names.
const guide = await this.helpers.httpRequest({ url: 'https://raw.githubusercontent.com/jdmaurer/ai-automation-lab/main/cases/eval-summary-drafter/memo-guide.md', json: false });
const lists = (guide.match(/^- \*\*[^*]+\(banned[^)]*\):\*\* .*$/gm) || [])
  .map(l => l.replace(/^- \*\*[^*]+\*\* /, '').replace(/\(.*$/, '').replace(/\.$/, ''));
const banned = lists.join(', ').split(',').map(w => w.trim()).filter(w => w && !/model names|run numbers/.test(w))
  .concat(setup.banned_words || []);
const hits = [...new Set(banned.filter(has))];
if (hits.length) fail('C4', `Banned words: ${hits.join(', ')}. Replace each with plain business wording.`);

// C5: the first result carries a test qualifier.
const s1 = (norm.split(/^## *2\./m)[0] || '');
if (!/in testing|test (messages|items|cases)|in \d+ test/i.test(s1)) fail('C5', 'Section 1 states a result without "in testing" or "in N test [items]".');

// C6: seven numbered sections, in order.
const nums = (norm.match(/^## *(\d)\./gm) || []).map(h => +h.replace(/\D/g, ''));
if (nums.join() !== '1,2,3,4,5,6,7') fail('C6', `Sections found: ${nums.join(', ') || 'none'}. Expected 1 to 7 in order.`);

// C7 and C8: length.
// Count body words only: headings and the "Prepared for" line don't count toward the page.
const bodyText = norm.split('\n').filter(l => !/^\s*#/.test(l) && !/prepared for:/i.test(l)).join(' ');
const words = bodyText.replace(/[*_>|-]/g, ' ').split(/\s+/).filter(w => /\w/.test(w)).length;
if (words > 650) fail('C7', `${words} words; the ceiling is about 650. Cut repetition and wording, never content.`);
else if (words > 500) flags.push(`C7: ${words} words, over the 500-word target (under the 650 ceiling).`);
const long = norm.replace(/\n/g, ' ').split(/(?<=[.!?])\s+/).filter(s => s.split(/\s+/).length > 20);
if (long.length) flags.push(`C8: ${long.length} sentence(s) over 20 words.`);

// Guide rules without a checklist item (added 2026-09-26).
// 2.3a: each group must be described. Same meaning, not exact words: at least half of the
// group's key words must appear in the memo ("single-service requests" counts for "requests for one service").
const stop = new Set(['for','or','and','the','a','an','of','to','with','one']);
const keyWords = t => t.toLowerCase().split(/[^a-z]+/).filter(w => w.length > 2 && !stop.has(w));
['handled_group', 'person_group'].forEach(k => {
  const kw = setup[k] ? keyWords(setup[k]) : [];
  if (kw.length && kw.filter(w => low.includes(w)).length / kw.length < 0.5)
    fail('2.3a', `The group "${setup[k]}" is never named. Say what the ${k === 'handled_group' ? facts.usefulness.total : facts.should_go_to_person.count} items were.`);
});
if (['below_target', 'no_target'].includes(facts.scenario) && !/right target|revisit (the|your) target|set a target/.test(low))
  fail('3.4', 'Section 7 must ask whether the target is still right (or ask for one if none was set).');
if (setup.harmful_action && low.includes(setup.harmful_action.toLowerCase()))
  fail('7.5', 'The harmful-action definition is pasted word for word. Say it naturally, for example "sent no message to the wrong team".');
if (/\bthe harmful action\b/.test(low)) fail('7.5', 'Uses the label "the harmful action". Name what actually happens instead.');
// Units: the gap to target is counted in items, never in points or percent.
const gap = low.match(/short by (\d+|one|two|three) (percentage points?|points?|percent|%)/);
if (u.short_by !== null && gap)
  fail('units', `"${gap[0]}" is wrong: the gap is ${u.short_by} ${setup.item_word}(s), not ${gap[2]}.`);
// Numbers in words (fractions, approximations) are new numbers the facts never approved.
const wordNums = [...new Set(low.match(/\b(approximately|roughly (?!1 in)|(one|two|three|four)[- ](half|halves|thirds?|quarters?|fifths?)|half of|majority|most of)\b/g) || [])];
if (wordNums.length)
  fail('C1', `Numbers in words or approximations: ${wordNums.join(', ')}. Use the exact approved count instead, or remove the sentence.`);
const missing = norm.match(/\[MISSING[^\]]*\]/g) || [];
if (missing.length) flags.push(`For you to fill: ${missing.join('; ')}`);

if (isRecheck) failures.forEach(f => flags.push(`Still failing after one fix: ${f.check}: ${f.detail}`));

return [{ json: { memo, failures, flags, word_count: words, fix_attempted: isRecheck,
  editor_changes: edit.changes, editor_flags: edit.editor_flags, facts, setup } }];

// BuildFixPrompt: one automatic fix attempt, with the exact failures named.
// No failures: return nothing, so the fix branch doesn't run and CheckMemo's output is final.
const c = $input.first().json;
if (!c.failures.length) return [];
const s = c.setup, f = c.facts;
const prompt = `Fix ONLY the problems listed below in this client memo. Change nothing else: keep every other sentence, every number, the recommendation, and the options as they are. Use only the facts given here.

PROBLEMS
${c.failures.map(x => `- ${x.check}: ${x.detail}`).join('\n')}

FACTS YOU MAY USE
- The ${f.usefulness.total} ${s.item_word}s the assistant should handle were ${s.handled_group}. The other ${f.should_go_to_person.count} were ${s.person_group}.
- The harmful outcome, in plain words: ${s.harmful_action}.
- The target is ${s.target_percent} percent. When the result is below target, section 7 asks: "Is ${s.target_percent} percent still the right target, now that you've seen the trade-off?"
- Quotable test items: ${f.referrals.quotable_examples.map(q => `"${q}"`).join(' ')}
- Write setup facts as natural sentences. Never paste them word for word, and never say "the harmful action".

Output only the full corrected memo in Markdown. No notes before or after it.

MEMO
${c.memo}`;
return [{ json: { prompt, approx_tokens: Math.round(prompt.length / 4) } }];

